initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let predictions = [];

  // 初期データの設定
  const storeTable = tables.find(t => t.tableName === '店舗マスタ') || { records: [] };
  const productTable = tables.find(t => t.tableName === '商品マスタ') || { records: [] };
  const predictionTable = tables.find(t => t.tableName === '需要予測結果') || { records: [] };
  const orderTable = tables.find(t => t.tableName === '発注データ') || { records: [] };

  stores = storeTable.records || [];
  predictions = predictionTable.records || [];

  // 店舗選択肢の初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // カテゴリ選択肢の初期化
  function initCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    const uniqueCategories = [...new Set(currentProducts.map(p => p.商品カテゴリID))];
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';
    uniqueCategories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-8)}</option>`;
      }
    });
  }

  // 商品テーブルの再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const tableContainer = container.querySelector('#product-table-container');
    const noStoreMessage = container.querySelector('#no-store-message');
    const noResultsMessage = container.querySelector('#no-results-message');

    if (!container.querySelector('#store-select').value) {
      tableContainer.classList.add('hidden');
      noStoreMessage.classList.remove('hidden');
      noResultsMessage.classList.add('hidden');
      return;
    }

    noStoreMessage.classList.add('hidden');

    if (products.length === 0) {
      tableContainer.classList.add('hidden');
      noResultsMessage.classList.remove('hidden');
      return;
    }

    noResultsMessage.classList.add('hidden');
    tableContainer.classList.remove('hidden');

    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const recommendedQty = prediction ? prediction.推奨発注数量 : 0;
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${currentStock}</td>
          <td>${predictedQty}</td>
          <td>${recommendedQty}</td>
          <td><input type="number" class="input order-qty-input" data-id="${product.商品ID}" min="0" style="width: 80px;" value="${recommendedQty}"></td>
          <td><input type="text" class="input order-reason-input" data-id="${product.商品ID}" placeholder="発注理由" style="width: 120px;"></td>
          <td>
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="increase">+</button>
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="decrease">-</button>
            <button class="action-btn order-single-btn" data-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePredictionSummary(products);
  }

  // 需要予測サマリーの更新
  function updatePredictionSummary(products) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      container.querySelector('#prediction-count').textContent = '-';
      container.querySelector('#prediction-total').textContent = '-';
      container.querySelector('#prediction-amount').textContent = '-';
      return;
    }

    const storePredictions = predictions.filter(p => p.店舗ID === storeId);
    const totalPredicted = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalAmount = storePredictions.reduce((sum, p) => {
      const product = products.find(prod => prod.商品ID === p.商品ID);
      return sum + ((p.推奨発注数量 || 0) * (product?.単価 || 0));
    }, 0);

    container.querySelector('#prediction-count').textContent = storePredictions.length;
    container.querySelector('#prediction-total').textContent = totalPredicted.toLocaleString();
    container.querySelector('#prediction-amount').textContent = '¥' + totalAmount.toLocaleString();
  }

  // 商品データの読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(1); // 商品マスタのインデックス
      if (products) {
        currentProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        initCategoryOptions();
        applyFilters();
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // フィルターの適用
  function applyFilters() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const productSearch = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      renderProducts([]);
      return;
    }

    let filtered = currentProducts.filter(product => {
      const matchesCategory = !categoryId || product.商品カテゴリID === categoryId;
      const matchesSearch = !productSearch || 
        (product.商品名 && product.商品名.toLowerCase().includes(productSearch)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(productSearch));

      return matchesCategory && matchesSearch;
    });

    renderProducts(filtered);
  }

  // バリデーション関数
  function validateOrderQuantity(qty) {
    if (qty === '' || qty === null || qty === undefined) {
      return { valid: false, message: '発注量を入力してください' };
    }

    const numQty = Number(qty);
    if (isNaN(numQty)) {
      return { valid: false, message: '発注量は数値で入力してください' };
    }

    if (numQty < 0) {
      return { valid: false, message: '発注量は正の数値を入力してください' };
    }

    if (numQty === 0) {
      return { valid: false, message: '発注量は1以上を入力してください' };
    }

    return { valid: true };
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日は開始日以降の日付を入力してください');
      return false;
    }
    return true;
  }

  // 発注処理
  async function processOrder(productIds) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const orderItems = [];
    let hasError = false;

    for (const productId of productIds) {
      const qtyInput = container.querySelector(`input.order-qty-input[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason-input[data-id="${productId}"]`);

      if (!qtyInput) continue;

      const qty = qtyInput.value.trim();
      const validation = validateOrderQuantity(qty);

      if (!validation.valid) {
        alert(`商品ID ${productId}: ${validation.message}`);
        qtyInput.focus();
        hasError = true;
        break;
      }

      const product = currentProducts.find(p => p.商品ID === productId);
      const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);

      orderItems.push({
        店舗ID: storeId,
        商品ID: productId,
        需要予測結果ID: prediction?.予測結果ID || null,
        発注日: new Date().toISOString(),
        納期予定日: new Date(Date.now() + (product?.リードタイム日数 || 3) * 24 * 60 * 60 * 1000).toISOString(),
        発注数量: Number(qty),
        予測数量: prediction?.予測数量 || 0,
        発注単価: product?.単価 || 0,
        発注金額: Number(qty) * (product?.単価 || 0),
        発注方法: prediction && Number(qty) === prediction.推奨発注数量 ? 'AI推奨採用' : 'AI推奨修正',
        発注ステータス: '発注済',
        仕入先ID: product?.仕入先ID || '',
        発注理由: reasonInput?.value || '',
        承認者ID: null,
        承認日時: null,
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      });
    }

    if (hasError) return;

    // 発注確認モーダルの表示
    showOrderConfirmation(orderItems);
  }

  // 発注確認モーダルの表示
  function showOrderConfirmation(orderItems) {
    const modal = container.querySelector('#order-modal');
    const detailsDiv = container.querySelector('#order-details');

    const totalAmount = orderItems.reduce((sum, item) => sum + item.発注金額, 0);
    const totalQty = orderItems.reduce((sum, item) => sum + item.発注数量, 0);

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>発注サマリー</strong><br>
        商品数: ${orderItems.length}点<br>
        総発注量: ${totalQty.toLocaleString()}個<br>
        総発注金額: ¥${totalAmount.toLocaleString()}
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>発注量</th>
              <th>単価</th>
              <th>金額</th>
              <th>発注理由</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => {
              const product = currentProducts.find(p => p.商品ID === item.商品ID);
              return `
                <tr>
                  <td>${product?.商品名 || ''}</td>
                  <td>${item.発注数量.toLocaleString()}</td>
                  <td>¥${item.発注単価.toLocaleString()}</td>
                  <td>¥${item.発注金額.toLocaleString()}</td>
                  <td>${item.発注理由 || '-'}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');

    // 発注実行ボタンのイベント
    container.querySelector('#btn-confirm-order').onclick = async () => {
      try {
        for (const item of orderItems) {
          await window.aivicApi.save(7, item); // 発注データテーブルのインデックス
        }
        alert('発注が完了しました');
        modal.classList.add('hidden');

        // 発注量と理由をリセット
        orderItems.forEach(item => {
          const qtyInput = container.querySelector(`input.order-qty-input[data-id="${item.商品ID}"]`);
          const reasonInput = container.querySelector(`input.order-reason-input[data-id="${item.商品ID}"]`);
          if (qtyInput) qtyInput.value = '';
          if (reasonInput) reasonInput.value = '';
        });

      } catch (error) {
        alert('発注処理中にエラーが発生しました');
        console.error(error);
      }
    };
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫', '予測需要量', '推奨発注量', '発注量', '発注理由'];
    const rows = Array.from(container.querySelectorAll('#product-tbody tr')).map(row => {
      const cells = row.querySelectorAll('td');
      const qtyInput = row.querySelector('.order-qty-input');
      const reasonInput = row.querySelector('.order-reason-input');

      return [
        cells[1]?.textContent || '',
        cells[2]?.textContent || '',
        cells[3]?.textContent || '',
        cells[4]?.textContent || '',
        cells[5]?.textContent || '',
        qtyInput?.value || '',
        reasonInput?.value || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();

  // イベントリスナーの設定
  container.querySelector('#store-select').addEventListener('change', () => {
    loadProducts();
  });

  container.querySelector('#category-select').addEventListener('change', applyFilters);
  container.querySelector('#product-search').addEventListener('input', applyFilters);

  container.querySelector('#btn-search').addEventListener('click', () => {
    if (validateDateRange()) {
      applyFilters();
    }
  });

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#product-search').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';
    renderProducts([]);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }
    const productIds = Array.from(checkedBoxes).map(cb => cb.dataset.id);
    processOrder(productIds);
  });

  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.id;
      const action = adjustBtn.dataset.action;
      const qtyInput = container.querySelector(`input.order-qty-input[data-id="${productId}"]`);

      if (qtyInput) {
        let currentQty = Number(qtyInput.value) || 0;
        if (action === 'increase') {
          qtyInput.value = currentQty + 1;
        } else if (action === 'decrease' && currentQty > 0) {
          qtyInput.value = currentQty - 1;
        }
      }
      return;
    }

    const orderBtn = e.target.closest('.order-single-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.id;
      processOrder([productId]);
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#order-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#order-modal')) {
      container.querySelector('#order-modal').classList.add('hidden');
    }
  });
}
